def smallestFactorialWithZeroes(k):
    def zeros(n):
        total = 0
        while n:
            n //= 5
            total += n
        return total

    lo, hi = 0, 5 * k
    while lo < hi:
        mid = (lo + hi) // 2
        if zeros(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo if zeros(lo) == k else -1
